workedExamples.question_text:
The plotted points lie on a straight line relating velocity $v(t)$ in m/s to time $t$ in seconds. Find its rate of change and hence write the equation of $v(t)$.
[tikz]
\begin{tikzpicture}[x=0.75cm,y=0.15cm]
\draw[black,->] (0,0) -- (6.7,0) node[right,font=\fontsize{10}{12}\selectfont] {$t$};
\draw[black,->] (0,0) -- (0,34) node[above,font=\fontsize{10}{12}\selectfont] {$v(t)$};
\node[below left,font=\fontsize{8.5}{10}\selectfont] at (0,0) {$0$};
\foreach \x in {2,4,6} {\draw[black] (\x,0.6) -- (\x,-0.6) node[below,font=\fontsize{8.5}{10}\selectfont] {$\x$};}
\foreach \y in {6,14,22,30} {\draw[black] (0.08,\y) -- (-0.08,\y) node[left,font=\fontsize{8.5}{10}\selectfont] {$\y$};}
\foreach \p in {(0,30),(2,22),(4,14),(6,6)} {\fill[blue!0!black] \p circle (2pt);}
\end{tikzpicture}
[/tikz]

mastery.question_text:
The graph shows a linear function relating velocity $v(t)$ in m/s and time $t$ in seconds. Find its rate of change and hence write the equation of $v(t)$.
[tikz]
\begin{tikzpicture}[x=0.7cm,y=0.3cm]
\draw[->] (0,0) -- (7,0) node[right] {$t$};
\draw[->] (0,0) -- (0,15) node[above] {$v(t)$};
\node[below left] at (0,0) {$0$};
\foreach \x in {2,4,6} {\draw (\x,0.2) -- (\x,-0.2) node[below] {$\x$};}
\foreach \y in {1,5,9,13} {\draw (0.12,\y) -- (-0.12,\y) node[left] {$\y$};}
\foreach \p in {(0,13),(2,9),(4,5),(6,1)} {\fill \p circle (2pt);}
\end{tikzpicture}
[/tikz]
